8	import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
9	import { rankTopN } from "@/lib/generator/rank";
10	import { rerank } from "@/lib/generator/rerank";
11	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
12	import {
13	  resolveLocation,
14	  roundCoord,
15	  LocationInputSchema,
16	  type LocationSource,
17	} from "@/lib/weather/location";
18	import type {
19	  GenerateResult,
20	  Look,
21	  LookPiece,
22	  UiOccasion,
23	  WeatherPayload,
24	} from "@/lib/generator/types";
25	
26	function currentSeason(d: Date): string {
27	  const m = d.getMonth();
28	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
29	}
30	
31	export async function generate(input: {
32	  occasion: UiOccasion;
33	  formality: number | null;
34	  mustColors: string[];
35	  city?: { lat: number; lon: number; label: string; source: LocationSource };
36	}): Promise<GenerateResult> {
37	  try {
38	    const supabase = await createClient();
39	    const {
40	      data: { user },
41	    } = await supabase.auth.getUser();
42	    if (!user) return { status: "error", message: "Not signed in" };
43	
44	    const { data: profile } = await supabase
45	      .from("profiles")
46	      .select("archetype, location_lat, location_lon, location_label")
47	      .eq("id", user.id)
48	      .single();
49	    const { data: itemsRaw } = await supabase
50	      .from("items")
51	      .select("*")
52	      .eq("user_id", user.id)
53	      .eq("archived", false);
54	    const items = itemsRaw ?? [];
55	    const byId = new Map(items.map((i) => [i.id, i]));
56	
57	    const loc = resolveLocation({ input: input.city, profile });
58	
59	    const now = new Date();
60	    const f = await fetchForecast(loc.lat, loc.lon);
61	    const advice = laterAdvice(f.hourly);
62	    const weather: WeatherPayload = {
63	      tempC: f.tempC,
64	      feelsLikeC: f.feelsLikeC,
65	      condition: f.condition,
66	      cityLabel: loc.label,
67	      timezone: f.timezone,
68	      laterSentence: advice.sentence,
69	      adviceClause: advice.adviceClause,
70	      laterLabel: "Later",
71	      hourly: f.hourly,
72	    };
73	
74	    const candItems: CandidateItem[] = items.map((i) => ({
75	      id: i.id,
76	      category: i.category,
77	      colors: i.colors ?? [],
78	      formality: i.formality,
79	      seasons: i.seasons ?? [],
80	      material: i.material,
81	    }));
82	    const band = applyFormalityOverride(occasionBand(input.occasion), input.formality);
83	    const combos = buildCandidates(candItems, {
84	      band,
85	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
86	      season: currentSeason(now),
87	      excludeItemIds: [],
88	      mustColors: input.mustColors,
89	      maxAccessories: 1,
90	    });
91	    if (combos.length === 0) return { status: "empty", weather };
92	
93	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
94	    const top = rankTopN(combos, { aesthetic, band }, 20);
95	
96	    const { picks } = await rerank({
97	      combos: top.map((t) =>
98	        t.items.map((ci) => {
99	          const it = byId.get(ci.id)!;
100	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
101	        }),
102	      ),
103	      aesthetic,
104	      occasion: input.occasion,
105	      weatherLabel: f.condition,
106	      tempC: f.tempC,
107	    });
108	
109	    const paths = Array.from(
110	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
111	    );
112	    const signed = await signItemImages(paths);
113	
114	    const looks: Look[] = picks.map((p) => {
115	      const combo = top[p.combo_index]?.items ?? top[0].items;
116	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
117	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
118	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
119	        itemId: d.id,
120	        category: d.category,
121	        subcategory: d.subcategory ?? null,
122	        brand: d.brand ?? null,
123	        name: d.name ?? null,
124	        colors: d.colors ?? [],
125	        cutoutUrl: signed.get(displayPath(d)) ?? "",
126	        slot: slots[idx],
127	      }));
128	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
129	    });
130	
131	    return { status: "ok", weather, looks };
132	  } catch (e) {
133	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
134	  }
135	}
